<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, watch } from 'vue'
import renderMathInElement from 'katex/contrib/auto-render'
import PlotlyChart from '../../../components/PlotlyChart.vue'
import { carterDuration, carterFetch } from '../../../engineering/waves/windWaves'
import { linspace } from '../../../engineering/numeric'
const fetchInput = reactive({ windSpeed: 10, extent: 10, ...JSON.parse(localStorage.getItem('marine-calculators:carter-fetch:v1') ?? '{}') })
const durationInput = reactive({ windSpeed: 10, extent: 4, ...JSON.parse(localStorage.getItem('marine-calculators:carter-duration:v1') ?? '{}') })
watch(fetchInput, value => localStorage.setItem('marine-calculators:carter-fetch:v1', JSON.stringify(value)), { deep: true }); watch(durationInput, value => localStorage.setItem('marine-calculators:carter-duration:v1', JSON.stringify(value)), { deep: true })
const fetchResult = computed(() => carterFetch(fetchInput)); const durationResult = computed(() => carterDuration(durationInput))
function graphData(input: { windSpeed: number; extent: number }, mode: 'fetch' | 'duration') {
  const calculate = mode === 'fetch' ? carterFetch : carterDuration
  const winds = linspace(0, Math.max(input.windSpeed * 2, 1), 100); const extents = linspace(0, Math.max(input.extent * 2, 1), 100); const current = calculate(input).significantWaveHeight
  return [{ x: winds, y: winds.map(windSpeed => calculate({ windSpeed, extent: input.extent }).significantWaveHeight), type: 'scatter' as const, mode: 'lines' as const, name: 'Constant ' + (mode === 'fetch' ? 'fetch' : 'duration'), line: { color: '#0879bd' }, hovertemplate: 'Wind speed: %{x:.2f} m/s<br>Hs: %{y:.2f} m<extra></extra>' }, { x: extents, y: extents.map(extent => calculate({ windSpeed: input.windSpeed, extent }).significantWaveHeight), type: 'scatter' as const, mode: 'lines' as const, name: 'Constant wind speed', xaxis: 'x2', yaxis: 'y2', line: { color: '#f07800' }, hovertemplate: `${mode === 'fetch' ? 'Fetch' : 'Duration'}: %{x:.2f} ${mode === 'fetch' ? 'km' : 'hours'}<br>Hs: %{y:.2f} m<extra></extra>` }, { x: [input.windSpeed], y: [current], type: 'scatter' as const, mode: 'markers' as const, marker: { color: '#111', size: 8 }, showlegend: false, hovertemplate: 'Current<extra></extra>' }, { x: [input.extent], y: [current], xaxis: 'x2', yaxis: 'y2', type: 'scatter' as const, mode: 'markers' as const, marker: { color: '#111', size: 8 }, showlegend: false, hovertemplate: 'Current<extra></extra>' }]
}
const fetchData = computed(() => graphData(fetchInput, 'fetch')); const durationData = computed(() => graphData(durationInput, 'duration'))
const layout = (mode: 'fetch' | 'duration') => ({ grid: { rows: 1, columns: 2, pattern: 'independent' as const }, xaxis: { title: { text: 'Wind Speed (m/s)' } }, yaxis: { title: { text: 'Hs (m)' } }, xaxis2: { title: { text: mode === 'fetch' ? 'Fetch (km)' : 'Duration (hours)' } }, yaxis2: { title: { text: 'Hs (m)' } }, showlegend: false })
onMounted(async () => { await nextTick(); const el=document.querySelector('.carter-background'); if(el) renderMathInElement(el as HTMLElement,{delimiters:[{left:'$$',right:'$$',display:true},{left:'$',right:'$',display:false}],throwOnError:false}) })
</script>
<template><section class="calculator" aria-labelledby="carter-title"><div class="calculator-heading"><h1 id="carter-title">Fetch Limited Waves (Carter, 1982)</h1></div>
<div class="calculator-grid"><article class="panel input-panel"><div class="panel-title input-title"><h2>Input</h2></div><label>Wind Speed <span>(m/s)</span><input v-model.number="fetchInput.windSpeed" type="number" min="0" max="35" /></label><label>Fetch <span>(km)</span><input v-model.number="fetchInput.extent" type="number" min="0" max="10000" /></label></article><article class="panel output-panel"><div class="panel-title output-title"><h2>Output</h2></div><dl class="results"><div><dt>Significant Wave Height (<i>H</i><sub>s</sub>)</dt><dd>{{ fetchResult.significantWaveHeight.toFixed(2) }} m</dd></div><div><dt>Peak Period (<i>T</i><sub>p</sub>)</dt><dd>{{ fetchResult.peakPeriod.toFixed(2) }} s</dd></div><div><dt>Mean Period (<i>T</i><sub>z</sub>)</dt><dd>{{ fetchResult.meanPeriod.toFixed(2) }} s</dd></div></dl></article><article class="panel charts-panel"><div class="panel-title graphical-title"><h2>Graphical</h2></div><div class="graphical-body"><PlotlyChart :data="fetchData" :layout="layout('fetch')" /></div></article></div>
<div class="calculator-heading subsection-heading"><h1>Duration Limited Waves (Carter, 1982)</h1></div><div class="calculator-grid"><article class="panel input-panel"><div class="panel-title input-title"><h2>Input</h2></div><label>Wind Speed <span>(m/s)</span><input v-model.number="durationInput.windSpeed" type="number" min="0" max="100" /></label><label>Duration <span>(hours)</span><input v-model.number="durationInput.extent" type="number" min="0" max="10000" /></label></article><article class="panel output-panel"><div class="panel-title output-title"><h2>Output</h2></div><dl class="results"><div><dt>Significant Wave Height (<i>H</i><sub>s</sub>)</dt><dd>{{ durationResult.significantWaveHeight.toFixed(2) }} m</dd></div><div><dt>Peak Period (<i>T</i><sub>p</sub>)</dt><dd>{{ durationResult.peakPeriod.toFixed(2) }} s</dd></div><div><dt>Mean Period (<i>T</i><sub>z</sub>)</dt><dd>{{ durationResult.meanPeriod.toFixed(2) }} s</dd></div></dl></article><article class="panel charts-panel"><div class="panel-title graphical-title"><h2>Graphical</h2></div><div class="graphical-body"><PlotlyChart :data="durationData" :layout="layout('duration')" /></div></article></div>
<article class="background-panel"><div class="background-title"><h2>Background</h2><span>−</span></div><div class="background-body carter-background"><p>Carter (1982) provides fetch- and duration-limited relationships that do not account for water depth.</p><div class="equation">$$H_s=0.0163F^{0.5}U_{10},\quad T_p=0.566F^{0.3}U_{10}^{0.4},\quad T_z=0.439F^{0.3}U_{10}^{0.4}$$</div><p>The results are capped at their fully developed limits.</p><div class="equation">$$H_s=0.0146U_{10}^{9/7}D^{5/7},\quad T_p=0.540U_{10}^{4/7}D^{3/7},\quad T_z=0.419U_{10}^{4/7}D^{3/7}$$</div><p><strong>References</strong><br />Carter, D. J. T. (1982). Prediction of wave height and period for a constant wind velocity using the JONSWAP formula. <em>Ocean Engineering, 9</em>, 17–33.<br />U.S. Army Corps of Engineers (2006). <em>Coastal Engineering Manual</em>, Section II-2-44.</p></div></article></section></template>
